def match(orders):
    trades = []
    buy_book = []  # [(price, arrival_time, id, qty)]
    sell_book = []  # [(price, arrival_time, id, qty)]
    order_map = {}  # id -> (side, price, arrival_time)
    arrival_time = 0

    for order in orders:
        if order[0] == 'cancel':
            cancel_id = order[1]
            if cancel_id in order_map:
                side, price, arr_time = order_map[cancel_id]
                del order_map[cancel_id]
                if side == 'buy':
                    buy_book[:] = [(p, t, oid, q) for p, t, oid, q in buy_book if oid != cancel_id]
                else:
                    sell_book[:] = [(p, t, oid, q) for p, t, oid, q in sell_book if oid != cancel_id]
        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[3] if order_type == 'market' else order[4]
            price = None if order_type == 'market' else order[3]

            if side == 'buy':
                # Match against sell book
                while qty > 0 and sell_book:
                    if order_type == 'market':
                        # Match at any price
                        sell_price, sell_arr_time, sell_id, sell_qty = sell_book[0]
                    else:
                        # Match at or below our price
                        if sell_book[0][0] > price:
                            break
                        sell_price, sell_arr_time, sell_id, sell_qty = sell_book[0]

                    trade_qty = min(qty, sell_qty)
                    trades.append([order_id, sell_id, sell_price, trade_qty])
                    qty -= trade_qty

                    if trade_qty == sell_qty:
                        sell_book.pop(0)
                        del order_map[sell_id]
                    else:
                        sell_book[0] = (sell_price, sell_arr_time, sell_id, sell_qty - trade_qty)

                # Add remaining to buy book if limit order
                if qty > 0 and order_type == 'limit':
                    order_map[order_id] = ('buy', price, arrival_time)
                    buy_book.append((price, arrival_time, order_id, qty))
                    buy_book.sort(key=lambda x: (-x[0], x[1]))

            else:  # sell
                # Match against buy book
                while qty > 0 and buy_book:
                    if order_type == 'market':
                        # Match at any price
                        buy_price, buy_arr_time, buy_id, buy_qty = buy_book[0]
                    else:
                        # Match at or above our price
                        if buy_book[0][0] < price:
                            break
                        buy_price, buy_arr_time, buy_id, buy_qty = buy_book[0]

                    trade_qty = min(qty, buy_qty)
                    trades.append([buy_id, order_id, buy_price, trade_qty])
                    qty -= trade_qty

                    if trade_qty == buy_qty:
                        buy_book.pop(0)
                        del order_map[buy_id]
                    else:
                        buy_book[0] = (buy_price, buy_arr_time, buy_id, buy_qty - trade_qty)

                # Add remaining to sell book if limit order
                if qty > 0 and order_type == 'limit':
                    order_map[order_id] = ('sell', price, arrival_time)
                    sell_book.append((price, arrival_time, order_id, qty))
                    sell_book.sort(key=lambda x: (x[0], x[1]))

            arrival_time += 1

    return trades

